"use client";

import { motion, useReducedMotion, type Transition } from "motion/react";
import {
  type ComponentPropsWithoutRef,
  type FocusEvent,
  type FormEvent,
  type KeyboardEvent,
  useEffect,
  useId,
  useRef,
  useState,
} from "react";

import { cn } from "@/lib/utils";

/** Props for a round search button that widens into a search field. */
export type SearchRevealProps = Omit<
  ComponentPropsWithoutRef<"form">,
  "children" | "onSubmit" | "defaultValue" | "style" | "onAnimationStart" | "onAnimationEnd" | "onAnimationIteration" | "onDrag" | "onDragStart" | "onDragEnd"
> & {
  /** Names the field and the closed button, for example "Search projects". */
  label?: string;
  /** Names the button while the field is open. */
  closeLabel?: string;
  placeholder?: string;
  value?: string;
  defaultValue?: string;
  onValueChange?: (value: string) => void;
  open?: boolean;
  /** A `defaultValue` with text also starts the field open, because a closed field never holds a query. */
  defaultOpen?: boolean;
  onOpenChange?: (open: boolean) => void;
  /** Runs when the person presses Enter in the field. */
  onSearch?: (value: string) => void;
};

// Damping 41 is 2 × √420, rounded up: critically damped, so the surface widens without overshoot.
const WIDEN: Transition = { type: "spring", stiffness: 420, damping: 41, mass: 1 };
const FIELD_IN: Transition = { duration: 0.18, ease: [0.23, 1, 0.32, 1], delay: 0.05 };
const INSTANT: Transition = { duration: 0 };

function SearchGlyph() {
  return (
    <svg viewBox="0 0 16 16" fill="currentColor" aria-hidden="true" className="size-4">
      <path
        fillRule="evenodd"
        d="M7 1.5a5.5 5.5 0 1 0 3.37 9.85l2.64 2.64a1 1 0 0 0 1.42-1.42l-2.64-2.64A5.5 5.5 0 0 0 7 1.5Zm0 2a3.5 3.5 0 1 1 0 7 3.5 3.5 0 0 1 0-7Z"
      />
    </svg>
  );
}

/**
 * A round search button that opens into a text field as one object. The
 * button's own surface widens, the icon stays where it was, and the field
 * fades in beside it. A closed field never holds a query: closing clears it.
 */
export function SearchReveal({
  label = "Search",
  closeLabel = "Close search",
  placeholder = "Search",
  value: valueProp,
  defaultValue = "",
  onValueChange,
  open: openProp,
  defaultOpen = false,
  onOpenChange,
  onSearch,
  className,
  onKeyDown,
  onBlur,
  ...formProps
}: SearchRevealProps) {
  const [ownValue, setOwnValue] = useState(defaultValue);
  // A field that starts with a query, controlled or not, starts open.
  const [ownOpen, setOwnOpen] = useState(defaultOpen || (valueProp ?? defaultValue) !== "");
  const value = valueProp ?? ownValue;
  const open = openProp ?? ownOpen;
  // Any close, including one the parent makes through `open`, clears the field's own query.
  const [shownOpen, setShownOpen] = useState(open);
  if (shownOpen !== open) {
    setShownOpen(open);
    if (!open && ownValue !== "") setOwnValue("");
  }
  // A query the parent supplies after the first render opens an uncontrolled field, so a closed field never holds one.
  const [shownValue, setShownValue] = useState(value);
  if (shownValue !== value) {
    setShownValue(value);
    if (openProp === undefined && shownValue === "" && value !== "" && !ownOpen) setOwnOpen(true);
  }
  const reduceMotion = useReducedMotion();
  const fieldId = useId();
  const rootRef = useRef<HTMLFormElement>(null);
  const buttonRef = useRef<HTMLButtonElement>(null);
  const inputRef = useRef<HTMLInputElement>(null);
  const wasOpen = useRef(open);
  // Whether focus was inside the search when the field left the page. React detaches the field's ref before it removes
  // the field, so the ref callback can still see the focus there. The effect below runs after the removal and cannot.
  const focusWasInside = useRef(false);
  const setInput = (input: HTMLInputElement | null) => {
    if (!input && inputRef.current) focusWasInside.current = rootRef.current?.contains(document.activeElement) ?? false;
    inputRef.current = input;
  };

  // Focus follows the object: into the field when it opens, back to the button
  // when it closes. A close caused by focus leaving does not pull focus back.
  useEffect(() => {
    if (wasOpen.current === open) return;
    wasOpen.current = open;
    if (open) inputRef.current?.focus();
    else if (focusWasInside.current) buttonRef.current?.focus();
  }, [open]);

  const setValue = (next: string) => {
    if (valueProp === undefined) setOwnValue(next);
    onValueChange?.(next);
  };

  const setOpen = (next: boolean) => {
    if (!next && value !== "") setValue("");
    if (openProp === undefined) setOwnOpen(next);
    onOpenChange?.(next);
  };

  const handleSubmit = (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    onSearch?.(value);
  };

  // Escape closes the field, which also clears the query.
  const handleKeyDown = (event: KeyboardEvent<HTMLFormElement>) => {
    onKeyDown?.(event);
    if (event.defaultPrevented || event.key !== "Escape" || !open) return;
    event.preventDefault();
    setOpen(false);
  };

  const handleBlur = (event: FocusEvent<HTMLFormElement>) => {
    onBlur?.(event);
    if (!open || value !== "" || rootRef.current?.contains(event.relatedTarget)) return;
    setOpen(false);
  };

  return (
    // The surface widens with a layout animation. The field's width is "auto", which a transform alone cannot reach,
    // and a layout animation still moves the surface with transforms and corrects the button and field inside it.
    <motion.form
      {...formProps}
      ref={rootRef}
      layout={!reduceMotion}
      transition={WIDEN}
      // Motion keeps a corner round while the surface scales only when the radius is a pixel number, so this one stays a number.
      style={{ borderRadius: 9999 }}
      role="search"
      onSubmit={handleSubmit}
      onKeyDown={handleKeyDown}
      onBlur={handleBlur}
      className={cn(
        "inline-flex max-w-full items-center rounded-full border border-border bg-card text-foreground has-focus-visible:ring-2 has-focus-visible:ring-ring has-focus-visible:ring-offset-2 has-focus-visible:ring-offset-background",
        className,
      )}
    >
      <motion.button
        ref={buttonRef}
        layout={reduceMotion ? false : "position"}
        transition={WIDEN}
        type="button"
        aria-label={open ? closeLabel : label}
        aria-expanded={open}
        aria-controls={open ? fieldId : undefined}
        // Keeps focus in the field while the button is pressed, so the press
        // closes the field once instead of a blur closing it and the click reopening it.
        onMouseDown={(event) => {
          if (open) event.preventDefault();
        }}
        onClick={() => setOpen(!open)}
        className="grid size-11 shrink-0 cursor-pointer touch-manipulation place-items-center rounded-full outline-none hover:bg-muted active:scale-95 motion-safe:transition motion-safe:duration-150 sm:size-9"
      >
        <SearchGlyph />
      </motion.button>
      {open ? (
        <motion.div
          layout={reduceMotion ? false : "position"}
          initial={{ opacity: 0 }}
          animate={{ opacity: 1 }}
          transition={reduceMotion ? INSTANT : { layout: WIDEN, opacity: FIELD_IN }}
          className="min-w-0"
        >
          <label htmlFor={fieldId} className="sr-only">
            {label}
          </label>
          <input
            ref={setInput}
            id={fieldId}
            type="search"
            value={value}
            onChange={(event) => setValue(event.target.value)}
            placeholder={placeholder}
            autoComplete="off"
            enterKeyHint="search"
            // Text is 1rem below `sm`, so a phone does not zoom the page on focus.
            className="h-11 w-44 max-w-full bg-transparent pr-4 pl-1 text-base text-foreground outline-none placeholder:text-muted-foreground sm:h-9 sm:w-56 sm:text-sm"
          />
        </motion.div>
      ) : null}
    </motion.form>
  );
}
